// 콜론 뒤에 타입을 쓰는 방법 타입 주석(타입 annotation)
// number
let num1 = 123;
let num2 = -123;
let num3 = 0.123;
let num4 = -0.123;
let num5 = Infinity;
let num6 = -Infinity;
let num7 = NaN;
num1.toFixed();
// string
let str1 = "hello";
let str2 = "hello"; // 작은 따옴표도 포함
let str3 = `hello`;
let str4 = `hello ${num1}`;
str1.toUpperCase();
// boolean
let bool1 = true;
let bool2 = false;
// null
let null1 = null;
// undefined
let unde1 = undefined;
// 리터럴 타입
// 리터럴 -> 값
let numA = 10; // 10이라는 값만 허용
let strA = "hello";
export {};
